import type { Request, Response } from 'express';

interface Policy {
  allowedScopes: string[];
}

// Parse and validate a policy document before it's used for any access
// decision — malformed JSON is rejected outright.
export function parsePolicy(raw: string): Policy {
  const parsed = JSON.parse(raw);
  if (!parsed || !Array.isArray(parsed.allowedScopes)) {
    throw new Error('invalid policy document');
  }
  return parsed;
}

export function applyPolicy(req: Request, res: Response): void {
  const policy = parsePolicy(String(req.body.policy));
  const requested = String(req.query.scope);
  if (!policy.allowedScopes.includes(requested)) {
    res.status(403).json({ message: 'Scope not permitted' });
    return;
  }
  res.json({ granted: true });
}

