import { connectorHeaders, OutboundHeaders } from './credentials';

export type OutboundOptions = { connectorId: string; method?: string; maxHops?: number };

export async function callConnector(target: string, opts: OutboundOptions) {
  const headers: OutboundHeaders = await connectorHeaders(opts.connectorId);
  const init = { method: opts.method ?? 'GET', headers, redirect: 'manual' as const };
  let url = target;
  for (let hop = 0; hop < (opts.maxHops ?? 4); hop++) {
    const res = await fetch(url, init);
    if (res.status < 300 || res.status > 399) return res;
    const location = res.headers.get('location');
    if (!location) return res;
    const next = new URL(location, url);
    if (next.origin !== new URL(url).origin) throw new Error('cross-origin redirect refused');
    url = next.toString();
  }
  throw new Error('too many hops');
}

