import { findBySubject, createFromSso, issueSession } from './accounts';

export type IdTokenClaims = {
  sub: string;
  email?: string;
  email_verified?: boolean;
};

export async function oidcCallback(claims: IdTokenClaims) {
  let account = await findBySubject(claims.sub);
